// <auto-generated />
using Fanex.Data.Repository;
using Fanex.Logging;
using Microsoft.AspNetCore.Mvc;
using Microsoft.OpenApi.Models;
using Prometheus;
using System.Reflection;
using PortalAPIs.Extensions;
using PortalAPIs.Middlewares;
using Microsoft.AspNetCore.Diagnostics;
using PortalAPIs.Services;

[assembly: ApiController]
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

var configuration = builder.Configuration;

builder.Services
    .AddSingleton<IDynamicRepository, DynamicRepository>()
    .AddFanexLogging(configuration)
    .AddFanexCaching(configuration)
    .AddOneBookUm(configuration)
    .AddInfrastructure()
    .AddFilters()
    .AddHealthChecks();

builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v1", new OpenApiInfo { Title = "Portal APIs", Version = "v1" });
    options.CustomSchemaIds(type => type.FullName);
    var xmlFilename = $"{Assembly.GetExecutingAssembly().GetName().Name}.xml";
    options.IncludeXmlComments(Path.Combine(AppContext.BaseDirectory, xmlFilename));
});

var app = builder.Build();
app.UseRouting();
app.UseHttpMetrics();

app.MapGet("/", () => "Portal APIs!!!");
app.UseUM(configuration);
app.UseFanexDataWithSqlServer(configuration, app.Environment);
app.UseMiddleware<ErrorHandlingMiddleware>();
app.MapControllers();
app.MapMetrics();

var isDevelopment = app.Environment.IsDevelopment();
app.UseSwagger();
app.UseSwaggerUI(options => options.SwaggerEndpoint("/swagger/v1/swagger.json", "Portal APIs v1"));

if (!isDevelopment)
{
    app.UseHsts();
    builder.WebHost.UseUrls("http://0.0.0.0:5000");
}

Logger.Log.Info($"{Assembly.GetExecutingAssembly().GetName().Name} has been started up.");


app.UseExceptionHandler(appError =>
{
    appError.Run(async context =>
    {
        var ex = context.Features.Get<IExceptionHandlerFeature>();
        if (ex == null)
        {
            return;
        }

        var serviceProvider = builder.Services.BuildServiceProvider();
        var logger = serviceProvider.GetService<ILoggerService>();
        await logger.Error(ex.Error);

        throw ex.Error;
    });
});

app.Run();